describe('Form Submission Confirmation Email', () => {
  const testEmail = 'testuser@example.com';
  const formUrl = '/contact-form';
  const apiBaseUrl = 'http://localhost:3000/api';

  beforeEach(() => {
    cy.visit(formUrl);
    cy.intercept('POST', `${apiBaseUrl}/submit-form`, {
      statusCode: 200,
      body: { success: true, message: 'Form submitted successfully' }
    }).as('formSubmission');

    cy.intercept('GET', `${apiBaseUrl}/emails`, {
      statusCode: 200,
      body: { emails: [] }
    }).as('getEmails');
  });

  it('should send confirmation email after successful form submission', () => {
    cy.get('input[name="name"]').type('John Doe');
    cy.get('input[name="email"]').type(testEmail);
    cy.get('textarea[name="message"]').type('This is a test message');

    cy.get('button[type="submit"]').click();

    cy.wait('@formSubmission').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
      expect(interception.response.body.success).to.be.true;
    });

    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Thank you for your submission');

    cy.wait(2000);

    cy.intercept('GET', `${apiBaseUrl}/emails?recipient=${testEmail}`, {
      statusCode: 200,
      body: {
        emails: [
          {
            id: 1,
            recipient: testEmail,
            subject: 'Confirmation: We received your message',
            body: 'Thank you for contacting us. We have received your message and will respond shortly.',
            sentAt: new Date().toISOString(),
            type: 'confirmation'
          }
        ]
      }
    }).as('confirmationEmailReceived');

    cy.request('GET', `${apiBaseUrl}/emails?recipient=${testEmail}`).then((response) => {
      expect(response.status).to.equal(200);
      expect(response.body.emails).to.have.length(1);
      expect(response.body.emails[0].type).to.equal('confirmation');
      expect(response.body.emails[0].recipient).to.equal(testEmail);
      expect(response.body.emails[0].subject).to.include('Confirmation');
    });
  });

  it('should handle form submission with special characters and send confirmation email', () => {
    const specialCharEmail = 'test+special.chars@example.co.uk';
    const specialCharName = "O'Brien-Smith & Co.";
    const specialCharMessage = 'Testing with special chars: !@#$%^&*()_+-=[]{}|;:,.<>?';

    cy.get('input[name="name"]').type(specialCharName);
    cy.get('input[name="email"]').type(specialCharEmail);
    cy.get('textarea[name="message"]').type(specialCharMessage);

    cy.get('button[type="submit"]').click();

    cy.wait('@formSubmission').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
      expect(interception.request.body.email).to.equal(specialCharEmail);
      expect(interception.request.body.name).to.equal(specialCharName);
    });

    cy.get('[data-testid="success-message"]').should('be.visible');

    cy.request('GET', `${apiBaseUrl}/emails?recipient=${encodeURIComponent(specialCharEmail)}`).then((response) => {
      expect(response.status).to.equal(200);
      expect(response.body.emails).to.have.length.greaterThan(0);
      const confirmationEmail = response.body.emails.find(e => e.type === 'confirmation');
      expect(confirmationEmail).to.exist;
      expect(confirmationEmail.recipient).to.equal(specialCharEmail);
    });
  });

  it('should not send confirmation email if form submission fails', () => {
    cy.intercept('POST', `${apiBaseUrl}/submit-form`, {
      statusCode: 400,
      body: { success: false, message: 'Form submission failed' }
    }).as('formSubmissionFailure');

    cy.get('input[name="name"]').type('Jane Doe');
    cy.get('input[name="email"]').type('jane@example.com');
    cy.get('textarea[name="message"]').type('Test message');

    cy.get('button[type="submit"]').click();

    cy.wait('@formSubmissionFailure').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
      expect(interception.response.body.success).to.be.false;
    });

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'error');

    cy.request({
      method: 'GET',
      url: `${apiBaseUrl}/emails?recipient=jane@example.com`,
      failOnStatusCode: false
    }).then((response) => {
      if (response.status === 200) {
        const confirmationEmails = response.body.emails.filter(e => e.type === 'confirmation');
        expect(confirmationEmails).to.have.length(0);
      }
    });
  });

  it('should resend confirmation email when user requests it', () => {
    cy.get('input[name="name"]').type('Bob Smith');
    cy.get('input[name="email"]').type('bob@example.com');
    cy.get('textarea[name="message"]').type('Test message for resend');

    cy.get('button[type="submit"]').click();

    cy.wait('@formSubmission');
    cy.get('[data-testid="success-message"]').should('be.visible');

    cy.get('[data-testid="resend-email-btn"]').should('be.visible').click();

    cy.intercept('POST', `${apiBaseUrl}/resend-confirmation-email`, {
      statusCode: 200,
      body: { success: true, message: 'Confirmation email resent' }
    }).as('resendEmail');

    cy.wait('@resendEmail').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
      expect(interception.response.body.success).to.be.true;
    });

    cy.get('[data-testid="resend-success-message"]').should('be.visible');
    cy.get('[data-testid="resend-success-message"]').should('contain', 'resent');
  });
});
